 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--phase',type=Path,required=True);ap.add_argument('--repo',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();assert not a.out.exists();a.out.mkdir();p=a.phase;src=p/'protected-QUIC-prefix-independent-source40-01';v1=p/'protected-QUIC-prefix-source-bound-whole40-01';v2=p/'protected-QUIC-prefix-source-bound-whole40-02';s=read(src/'summary.json');one=read(v1/'summary.json');two=read(v2/'summary.json');assert one['failure_count']==two['failure_count']==0;assert one['results']==two['results'];assert (v1/'changed-PDU-source-anchors.json').read_bytes()==(v2/'changed-PDU-source-anchors.json').read_bytes();assert two['native_ALPN_equal_independent_authenticated_EncryptedExtensions']and two['peer_identity_verification_not_inferred'];assert two['required_negative_controls_rejected'][:-1]==one['required_negative_controls_rejected'];assert two['required_negative_controls_rejected'][-1]=='ALPN-not-source-EE'
