  manifest.append({'absolute_path':str(f),'bytes':len(raw),'SHA256':sha(f),'role':role,'kind':kind,'source_only':True,'embedded_actual_capture_packet_or_secret_observed':False,'privacy_scan_counts':{'NSS_secret_blob_patterns':secret_blob,'PEM_private_key_headers':pem_private,'hex_literals_128bytes_or_more':long_literal}})
